import{c as o,Z as t,Q as e,j as l,m as r,o as s}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"蒹葭","description":"","frontmatter":{"title":"蒹葭","author":"佚名","dynasty":"先秦"},"headers":[],"relativePath":"books/shici/shijing/2.md","filePath":"books/shici/shijing/2.md"}'),n={name:"books/shici/shijing/2.md"};function h(u,a,c,d,q,p){const i=t("PoemNav");return e(),l("div",null,[a[0]||(a[0]=r('<h1 id="蒹葭" tabindex="-1">蒹葭 <a class="header-anchor" href="#蒹葭" aria-label="Permalink to &quot;蒹葭&quot;">​</a></h1><p><strong>《诗经·秦风》</strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>蒹葭苍苍，白露为霜。所谓伊人，在水一方。 溯洄从之，道阻且长。溯游从之，宛在水中央。 蒹葭萋萋，白露未晞。所谓伊人，在水之湄。 溯洄从之，道阻且跻。溯游从之，宛在水中坻。 蒹葭采采，白露未已。所谓伊人，在水之涘。 溯洄从之，道阻且右。溯游从之，宛在水中沚。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>蒹葭：芦苇</li><li>苍苍：茂盛的样子，一说青色</li><li>伊人：那个人，指所思慕之人</li><li>溯洄：逆流而上</li><li>溯游：顺流而下</li><li>萋萋：茂盛的样子</li><li>晞：干</li><li>湄：水和草交接的地方，即岸边</li><li>跻：升高，指道路险峻</li><li>坻：水中的小沙洲</li><li>采采：茂盛鲜明的样子</li><li>已：止，干</li><li>涘：水边</li><li>右：迂回曲折</li><li>沚：水中的小块陆地</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>河边芦苇青苍苍，秋深露水结成霜。意中之人在何处？就在河水那一方。 逆着流水去找她，道路险阻又太长。顺着流水去找她，仿佛在那水中央。 河边芦苇密又繁，清晨露水未曾干。意中之人在何处？就在河岸那一边。 逆着流水去找她，道路险阻攀登难。顺着流水去找她，仿佛就在水中滩。 河边芦苇密稠稠，早晨露水未全收。意中之人在何处？就在水边那一头。 逆着流水去找她，道路险阻曲难求。顺着流水去找她，仿佛就在水中洲。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>《蒹葭》是《诗经·秦风》中的名篇，是一首怀人诗。全诗以秋水蒹葭为背景，抒发了对&quot;伊人&quot;的深切思念与追寻不得的惆怅之情。诗中以&quot;白露为霜&quot;&quot;白露未晞&quot;&quot;白露未已&quot;点明时间的推移，以&quot;道阻且长&quot;&quot;道阻且跻&quot;&quot;道阻且右&quot;渲染追寻的艰难，意境朦胧凄清，具有极高的艺术感染力。此诗对后世文学影响深远，成为中国古典诗歌中&quot;秋水伊人&quot;意象的源头。</p><hr><h2 id="关于《诗经》" tabindex="-1">关于《诗经》 <a class="header-anchor" href="#关于《诗经》" aria-label="Permalink to &quot;关于《诗经》&quot;">​</a></h2><blockquote><p>《诗经》是中国古代诗歌开端，最早的一部诗歌总集，收集了西周初年至春秋中叶的诗歌305篇，又称“诗三百”。作者多不可考，相传为孔子编订。</p><p><a href="/books/shici/shijing.html">查看诗经详情 →</a></p></blockquote>',13)),s(i)])}const b=o(n,[["render",h]]);export{m as __pageData,b as default};
